{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles RSO no-fault eviction relocation assistance","requirement":"A landlord terminating an RSO tenancy for a no-fault reason must file a Declaration of Intent to Evict with LAHD before serving notice, file a copy of the notice within 3 days, and pay relocation assistance within 15 days of service.","key_value":"Eligible: $11,000 (under 3 years) / $14,400 (3+ years); Qualified: $23,150 / $27,400; 2026-07-01 to 2027-06-30","coverage_conditions":"Units covered by the Rent Stabilization Ordinance (RSO) whose tenancy is terminated for a no-fault reason such as owner or relative occupancy, demolition, order to vacate, or Ellis Act withdrawal.","applicability":{"conditions":[{"type":"other","text":"only units covered by the Rent Stabilization Ordinance (RSO)"}],"per_tenancy":"No-fault eviction grounds: owner, relative or resident manager occupancy; demolition; withdrawal from rental housing use; order to vacate","coverage_quotes":["All tenant not- at-fault evictions require payment of relocation assistance and the filing of a Declaration of Intent to Evict form with the Los Angeles Housing Department (LAHD) before evicting tenants from units covered by the Rent Stabilization Ordinance (RSO) or the Just Cause Ordinance (JCO)."]},"exemptions":"Evicting a resident manager to replace with another resident manager; eviction required by hazardous conditions from a natural disaster not caused by landlord negligence; offset of accumulated rent; Mom and Pop properties of four or fewer units may pay reduced relocation assistance for owner or relative occupancy.","penalty":"Tenant may raise non-payment of relocation assistance as an affirmative defense to eviction, may file a complaint with LAHD, and may seek a private right of action.","effective_date":"2026-07-01","valid_through":"2027-06-30","citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"All tenant not- at-fault evictions require payment of relocation assistance and the filing of a Declaration of Intent to Evict form with the Los Angeles Housing Department (LAHD) before evicting tenants from units covered by the Rent Stabilization Ordinance (RSO) or the Just Cause Ordinance (JCO).","interaction":"RSO relocation amounts must be enhanced for lower income tenants under the State Housing Crisis Act, regardless of RPO applicability.","relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles JCO no-fault eviction relocation assistance","requirement":"A landlord terminating a JCO tenancy for a no-fault reason must file a Declaration of Intent to Evict with LAHD, file a copy of the notice within 3 business days, and pay relocation assistance; single-family units owned by natural persons get one month's rent.","key_value":"Eligible: $11,000 (under 3 years) / $14,400 (3+ years); Qualified: $23,150 / $27,400; single-family natural-person owner: 1 month's rent","coverage_conditions":"Units covered by the Just Cause Ordinance (JCO) terminated for a no-fault reason; single-family dwellings subject to the JCO owned by a natural person with no more than four dwelling units and a single-family home on a separate lot.","applicability":{"conditions":[{"type":"other","text":"only units covered by the Just Cause Ordinance (JCO)"}],"per_tenancy":"No-fault eviction grounds, including demolition for new construction under LAMC 165.03.I","coverage_quotes":["All tenant not- at-fault evictions require payment of relocation assistance and the filing of a Declaration of Intent to Evict form with the Los Angeles Housing Department (LAHD) before evicting tenants from units covered by the Rent Stabilization Ordinance (RSO) or the Just Cause Ordinance (JCO)."]},"exemptions":"Resident manager replaced by another resident manager; hazardous conditions from a natural disaster not caused by landlord negligence; offset of accumulated rent; LAMC 151.30(E) does not apply to single-family natural-person owners.","penalty":"Tenant may raise non-payment of relocation assistance as an affirmative defense to eviction; tenant may file a LAHD complaint or seek a private right of action.","effective_date":"2026-07-01","valid_through":"2027-06-30","citation":"Los Angeles Just Cause Ordinance (L.A.M.C. §165.00 et seq.)","quoted_span":"When the residential real property is a single-family dwelling subject to the JCO and the owner is a natural person, including natural persons who hold properties in a trust or registered legal entity controlled by that natural person, who owns no more than four dwelling units and a single-family home on a separate lot in the City of Los Angeles: one month’s rent that was in effect when the landlord served the written notice to terminate the tenancy, as either a monetary payment or credit.","interaction":"City relocation amounts must be the higher of the State Housing Crisis Act or City amounts and enhanced for lower income tenants.","relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles Resident Protections Ordinance demolition relocation","requirement":"An owner demolishing a Protected Unit for new construction within 5 years after filing the Notice of Intent to Withdraw or Declaration of Intent to Evict must follow RPO relocation and occupant protections and pay the highest of State and City amounts.","key_value":"$250,000 per displaced unit (minimum penalty)","coverage_conditions":"Protected Units demolished for new construction: units under rent or price control within the past five years, lower income units, and Ellis Act withdrawals within the past 10 years.","applicability":{"conditions":[{"type":"other","text":"only Protected Units that will be demolished for the purpose of new construction"}],"per_tenancy":"Demolition for new construction within 5 years after the Notice of Intent to Withdraw or Declaration of Intent to Evict is filed","coverage_quotes":["The RPO only applies to Protected Units that will be demolished for the purpose of new construction."]},"exemptions":null,"penalty":"Financial penalties starting at $250,000 per displaced unit and withholding of LAHD permit clearances.","effective_date":"2025-02-11","valid_through":null,"citation":"Resident Protections Ordinance (RPO)","quoted_span":"Failure to comply with the RPO may result in financial penalties starting at $250,000 per displaced unit and withholding of LAHD permit clearances.","interaction":"Requires payment of the highest of State (Housing Crisis Act) and City relocation amounts.","relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
